<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $start=trim((string)($_GET['start']??date('Y-m-01'))); $end=trim((string)($_GET['end']??date('Y-m-d'))); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))$start=date('Y-m-01'); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end))$end=date('Y-m-d'); if($start>$end){$t=$start;$start=$end;$end=$t;} $from=$start.' 00:00:00'; $to=date('Y-m-d',strtotime($end.' +1 day')).' 00:00:00'; $one=function(string $sql)use($db,$from,$to){$q=$db->prepare($sql);$q->execute([$from,$to]);return (float)$q->fetchColumn();}; $sales=$one('SELECT COALESCE(SUM(total),0) FROM sales WHERE created_at>=? AND created_at<?'); $collected=$one('SELECT COALESCE(SUM(paid),0) FROM sales WHERE created_at>=? AND created_at<?'); $purchases=$one('SELECT COALESCE(SUM(subtotal),0) FROM purchases WHERE created_at>=? AND created_at<?'); $purchasePaid=$one('SELECT COALESCE(SUM(paid),0) FROM purchases WHERE created_at>=? AND created_at<?'); $expenses=$one('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE created_at>=? AND created_at<?'); $saleReturns=$one("SELECT COALESCE(SUM(amount),0) FROM returns WHERE return_type='sale' AND created_at>=? AND created_at<?"); $purchaseReturns=$one("SELECT COALESCE(SUM(amount),0) FROM returns WHERE return_type='purchase' AND created_at>=? AND created_at<?"); $cogs=$one('SELECT COALESCE(SUM(si.quantity_units*COALESCE(b.purchase_unit_cost,m.purchase_price)),0) FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN medicines m ON m.id=si.medicine_id LEFT JOIN batches b ON b.id=si.batch_id WHERE s.created_at>=? AND s.created_at<?'); $netSales=max(0,$sales-$saleReturns); $netPurchases=max(0,$purchases-$purchaseReturns); $grossProfit=$netSales-$cogs; $netProfit=$grossProfit-$expenses; $customerDue=(float)$db->query("SELECT COALESCE(SUM(total-paid),0) FROM sales WHERE payment_method='credit' AND total>paid")->fetchColumn(); $supplierDue=(float)$db->query('SELECT COALESCE(SUM(subtotal-paid),0) FROM purchases WHERE subtotal>paid')->fetchColumn(); $low=$db->query("SELECT m.name,m.reorder_level,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id WHERE m.active=1 GROUP BY m.id HAVING stock<=m.reorder_level ORDER BY stock")->fetchAll(); $expiry=$db->query("SELECT m.name,b.batch_no,b.expiry_date,b.units_remaining FROM batches b JOIN medicines m ON m.id=b.medicine_id WHERE b.expiry_date IS NOT NULL AND b.expiry_date<=DATE_ADD(CURDATE(),INTERVAL 90 DAY) AND b.units_remaining>0 ORDER BY b.expiry_date")->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">BUSINESS INTELLIGENCE</div><h1>Reports</h1><p>Sales, purchases, expenses, profit, customer dues, supplier dues and returns.</p></div></div><section class="panel"><form method="get" class="grid"><label>From<input type="date" name="start" value="<?=e($start)?>"></label><label>To<input type="date" name="end" value="<?=e($end)?>"></label><button class="btn">Apply Period</button></form></section><div class="stats"><div class="stat"><small>Gross Sales</small><b>Rs. <?=money($sales)?></b></div><div class="stat"><small>Customer Returns</small><b>Rs. <?=money($saleReturns)?></b></div><div class="stat"><small>Net Sales</small><b>Rs. <?=money($netSales)?></b></div><div class="stat"><small>Collected</small><b>Rs. <?=money($collected)?></b></div></div><div class="stats"><div class="stat"><small>Purchases</small><b>Rs. <?=money($purchases)?></b></div><div class="stat"><small>Supplier Returns</small><b>Rs. <?=money($purchaseReturns)?></b></div><div class="stat"><small>Net Purchases</small><b>Rs. <?=money($netPurchases)?></b></div><div class="stat"><small>Purchase Paid</small><b>Rs. <?=money($purchasePaid)?></b></div></div><div class="stats"><div class="stat"><small>Cost of Goods Sold</small><b>Rs. <?=money($cogs)?></b></div><div class="stat"><small>Gross Profit</small><b>Rs. <?=money($grossProfit)?></b></div><div class="stat"><small>Expenses</small><b>Rs. <?=money($expenses)?></b></div><div class="stat"><small>Net Profit</small><b>Rs. <?=money($netProfit)?></b></div></div><div class="stats"><div class="stat"><small>Customer Due</small><b>Rs. <?=money($customerDue)?></b></div><div class="stat"><small>Supplier Due</small><b>Rs. <?=money($supplierDue)?></b></div><div class="stat"><small>Customer Returns</small><b>Rs. <?=money($saleReturns)?></b></div><div class="stat"><small>Supplier Returns</small><b>Rs. <?=money($purchaseReturns)?></b></div></div><section class="panel"><h2>Low Stock</h2><table><tr><th>Medicine</th><th>Stock</th><th>Reorder Level</th></tr><?php foreach($low as $r):?><tr><td><?=e($r['name'])?></td><td><?=number_format((float)$r['stock'])?></td><td><?=number_format((float)$r['reorder_level'])?></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Expiry Within 90 Days</h2><table><tr><th>Medicine</th><th>Batch</th><th>Expiry</th><th>Units</th></tr><?php foreach($expiry as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['batch_no']??'—')?></td><td><?=e($r['expiry_date'])?></td><td><?=number_format((float)$r['units_remaining'])?></td></tr><?php endforeach;?></table></section></main></body></html>